   "event": "p95 latency first at or above 1s on gateway, orders and inventory",
   "evidence_ids": [
    "ev-7ee29eff609f",
    "ev-506ce368ec1d",
    "ev-d850cf508436"
   ]
  },
  {
   "time": "2026-10-24T00:29:17Z",
   "event": "First sampled slow checkout trace: dominant self time in inventory POST /reserve, release 3.1.5",
   "evidence_ids": [
    "ev-52f825c98c5f"
   ]
  },
  {
   "time": "2026-10-24T00:29:34Z",
   "event": "Last sampled slow trace; checkout still returning 201 in 1.31-1.83s",
   "evidence_ids": [
    "ev-52f825c98c5f"
   ]
  }
 ],
 "ruled_out": [
  {
   "statement": "An error cascade is unlikely: the 5xx ratio was 0% on all three services, and the sampled traces have an empty error path with root status 201.",
   "evidence_ids": [
    "ev-7ee29eff609f",
    "ev-506ce368ec1d",
    "ev-d850cf508436",
    "ev-52f825c98c5f"
   ]
  },
  {
   "statement": "Gateway and orders are unlikely to be the origin. In the sampled traces, dominant self time is in inventory POST /reserve and not in those services.",
   "evidence_ids": [
    "ev-52f825c98c5f"
   ]
  }
 ],
 "unknowns": [
  "No deployment records were returned for the window. It is unknown whether inventory 3.1.5, or any other change, was rolled out shortly before 00:27:22Z.",
  "Logs returned nothing. There are no inventory application logs (for example lock waits, DB slowness or GC) to explain why POST /reserve slowed.",
  "There are no metrics for inventory's own dependencies (database, cache), so a downstream cause beneath inventory cannot be confirmed or excluded.",
  "The traces were sampled only from 00:29:17Z onward, so the attribution to inventory covers the later part of the incident, not its onset."
 ],
 "recommended_actions": [
  {
   "action": "Investigate inventory POST /reserve: profile it and check its database or lock contention and resource saturation during 00:27-00:30Z.",
   "rationale": "Trace self time puts the latency in this operation, and the upstream services only show waiting.",
   "evidence_ids": [
    "ev-52f825c98c5f",
    "ev-506ce368ec1d"
   ]
  },
  {
   "action": "Check deployment history outside the collected source (CI/CD, kubectl rollout history) for when inventory 3.1.5 was rolled out. If it was recent, consider rolling back.",
   "rationale": "The deployment source returned no records, so a recent inventory change can be neither confirmed nor excluded.",
   "evidence_ids": [
    "src-deployments",
    "ev-52f825c98c5f"
   ]
  },
  {
   "action": "Re-query inventory logs with a wider window or a different index or filter.",
   "rationale": "The logs source returned nothing, leaving no explanation for the slowdown.",
   "evidence_ids": [
    "src-logs"
   ]
  },
  {
   "action": "Compare the current inventory request rate with its capacity, and scale out if it is saturated.",
   "rationale": "Request rates rose toward the end of the window together with latency.",
   "evidence_ids": [
    "ev-506ce368ec1d"
   ]
  }
 ]
}
